<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
$token=(string)($_GET['token']??$_POST['token']??'');
$q=db()->prepare("SELECT l.*,b.booking_reference,b.check_in,b.check_out,p.name property_name,g.id guest_id,g.first_name,g.last_name FROM booking_checkin_links l JOIN supplier_bookings b ON b.id=l.booking_id JOIN properties p ON p.id=b.property_id LEFT JOIN booking_guests bg ON bg.booking_id=b.id AND bg.is_primary=true LEFT JOIN guest_profiles g ON g.id=bg.guest_id WHERE l.token_hash=? AND l.status='active' AND l.expires_at>now()");$q->execute([hash('sha256',$token)]);$link=$q->fetch();if(!$link){http_response_code(404);exit('Bu check-in bağlantısı geçersiz veya süresi dolmuş.');}$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!isset($_POST['consent']))exit('Aydınlatma/onay seçimi zorunludur.');$pdo=db();$pdo->beginTransaction();try{$identity=trim((string)$_POST['identity_number']);$pdo->prepare("UPDATE guest_profiles SET phone=?,nationality=?,identity_type=?,identity_number=?,preferences=jsonb_set(preferences,'{online_checkin}','true'::jsonb,true) WHERE id=?")->execute([trim((string)$_POST['phone'])?:null,strtoupper(trim((string)$_POST['nationality'])?:'TR'),$_POST['identity_type']??null,$identity,$link['guest_id']]);$pdo->prepare("UPDATE booking_guests SET checkin_status='submitted' WHERE booking_id=? AND guest_id=?")->execute([$link['booking_id'],$link['guest_id']]);$pdo->prepare("INSERT INTO guest_document_records(guest_id,booking_id,document_type,document_number_masked,verification_status,consent_at) VALUES(?,?,?,?, 'pending',now())")->execute([$link['guest_id'],$link['booking_id'],$_POST['identity_type']??'identity',substr($identity,0,2).'***']);$pdo->prepare("UPDATE booking_checkin_links SET status='submitted',submitted_at=now() WHERE id=?")->execute([$link['id']]);$pdo->commit();$message='Bilgileriniz alınmıştır. Resepsiyon kontrolünden sonra girişiniz tamamlanacaktır.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$message='İşlem tamamlanamadı.';}}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online check-in</title><style>body{font-family:Arial;background:#f6f7f4;color:#14241f}.w{max-width:600px;margin:40px auto;background:#fff;padding:24px}input,select,button{width:100%;box-sizing:border-box;padding:11px;margin:6px 0}button{background:#14241f;color:white;border:0}</style></head><body><main class="w"><h1><?=htmlspecialchars($link['property_name'])?></h1><p><?=htmlspecialchars($link['booking_reference'])?> · <?=htmlspecialchars($link['check_in'])?> / <?=htmlspecialchars($link['check_out'])?></p><?php if($message):?><p><?=htmlspecialchars($message)?></p><?php else:?><form method="post"><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><input value="<?=htmlspecialchars($link['first_name'].' '.$link['last_name'])?>" disabled><input name="phone" placeholder="Telefon"><input name="nationality" value="TR" maxlength="2" placeholder="Uyruk"><select name="identity_type"><option value="identity">Kimlik</option><option value="passport">Pasaport</option></select><input name="identity_number" placeholder="Kimlik / pasaport no" required><label><input type="checkbox" name="consent" value="1" required> Aydınlatma metnini okudum ve giriş bilgilerimin işlem amacıyla kullanılmasını kabul ediyorum.</label><button>Bilgileri gönder</button></form><?php endif;?></main></body></html>
